-- TORVO V2 sales team foundation. Staging review required.
create table if not exists salesman_area_mappings (id uuid primary key default gen_random_uuid(),salesman_id uuid not null references app_users(id),state text not null,district text,city text,active boolean not null default true,assigned_by uuid not null references app_users(id),assigned_at timestamptz not null default now(),ended_at timestamptz,check(city is null or district is not null));
create index if not exists idx_salesman_area_active on salesman_area_mappings(salesman_id,active,state,district,city);
create table if not exists salesman_dealer_mappings (id uuid primary key default gen_random_uuid(),salesman_id uuid not null references app_users(id),dealer_id uuid not null references dealers(id),active boolean not null default true,assigned_by uuid not null references app_users(id),assigned_at timestamptz not null default now(),ended_at timestamptz,transfer_reason text);
create unique index if not exists idx_one_active_salesman_per_dealer on salesman_dealer_mappings(dealer_id) where active=true;
create index if not exists idx_salesman_dealers_active on salesman_dealer_mappings(salesman_id,active);
create table if not exists salesman_targets (id uuid primary key default gen_random_uuid(),salesman_id uuid not null references app_users(id),period_type text not null check(period_type in('monthly','quarterly','financial_year')),period_start date not null,period_end date not null,sales_value_target numeric not null default 0,billed_dealer_target integer not null default 0,new_dealer_target integer not null default 0,assigned_by uuid not null references app_users(id),created_at timestamptz not null default now(),check(period_end>=period_start),unique(salesman_id,period_type,period_start,period_end));
